/* Sync Studio: dotted globe centred on Agadir. Vanilla JS, no dependencies. */
(function () {
  if (window.__ssGlobe) return;
  window.__ssGlobe = true;
  var MASK = "";
  var MW = 720, MH = 360, bits = null;
  function land(lon, lat) {
    if (!bits) { var s = atob(MASK); bits = new Uint8Array(s.length); for (var i = 0; i < s.length; i++) bits[i] = s.charCodeAt(i); }
    var x = Math.floor((lon + 180) * 2), y = Math.floor((90 - lat) * 2);
    if (x < 0 || x >= MW || y < 0 || y >= MH) return 0;
    var k = y * MW + x; return (bits[k >> 3] >> (k & 7)) & 1;
  }
  var RAD = Math.PI / 180;
  var AGADIR = [-9.6, 30.42];
  var LINKS = [[-7.99, 31.63], [-7.59, 33.57], [-5.0, 34.03], [-5.83, 35.76], [-9.77, 31.51]];
  var reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;

  function init(canvas) {
    if (canvas.dataset.fx) return;
    canvas.dataset.fx = "1";
    var ctx = canvas.getContext("2d");
    var W = 0, H = 0, dpr = 1, R = 0, cx = 0, cy = 0, pts = null, n = 0, visible = true, raf = 0, px = 0, tpx = 0;
    var mono = (getComputedStyle(document.documentElement).getPropertyValue("--font-jetbrains") || "monospace").trim();
    var C = {};
    function palette() {
      var cs = getComputedStyle(document.documentElement);
      function v(name, d) { return (cs.getPropertyValue(name) || "").trim() || d; }
      C = { dot: v("--globe-dot", "201,209,224"), line: v("--globe-line", "58,72,104"), accent: v("--globe-accent", "0,229,255"), text: v("--globe-text", "230,234,242"), muted: v("--globe-muted", "143,163,199") };
    }
    palette();
    new MutationObserver(function () { palette(); frame(performance.now()); }).observe(document.documentElement, { attributes: true, attributeFilter: ["data-ss-theme"] });

    function build() {
      var r = canvas.getBoundingClientRect();
      W = r.width; H = r.height; dpr = Math.min(2, window.devicePixelRatio || 1);
      canvas.width = Math.round(W * dpr); canvas.height = Math.round(H * dpr);
      R = Math.max(W * 0.56, 520);
      cx = W / 2; cy = 26 + R;
      var step = 7.2 / (R * RAD); // ~7px between dots
      var arr = [];
      for (var lat = -84; lat <= 84; lat += step) {
        var c = Math.cos(lat * RAD), ls = step / Math.max(c, 0.05);
        for (var lon = -180; lon < 180; lon += ls) {
          if (land(lon, lat)) arr.push(c * Math.sin(lon * RAD), Math.sin(lat * RAD), c * Math.cos(lon * RAD));
        }
      }
      pts = new Float32Array(arr); n = arr.length / 3;
    }
    function xyz(lon, lat) { var c = Math.cos(lat * RAD); return [c * Math.sin(lon * RAD), Math.sin(lat * RAD), c * Math.cos(lon * RAD)]; }

    function frame(t) {
      var l0 = (AGADIR[0] + 10 * Math.sin(t / 9000) + px * 6) * RAD, p0 = -29 * RAD;
      var cl = Math.cos(l0), sl = Math.sin(l0), cp = Math.cos(p0), sp = Math.sin(p0);
      function proj(x, y, z) {
        var x1 = x * cl - z * sl, z1 = x * sl + z * cl;
        var y2 = y * cp - z1 * sp, z2 = y * sp + z1 * cp;
        return [cx + x1 * R, cy - y2 * R, z2];
      }
      function fade(sy) { var f = (H - sy) / (H * 0.55); return f < 0 ? 0 : f > 1 ? 1 : f; }

      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, W, H);

      // limb + atmosphere ring
      for (var a = 0; a < 2; a++) {
        var rr = a ? R * 1.018 : R;
        for (var s = 0; s < 90; s++) {
          var a0 = Math.PI + (s / 90) * Math.PI, a1 = Math.PI + ((s + 1) / 90) * Math.PI;
          var my = cy + Math.sin((a0 + a1) / 2) * rr, f = fade(my);
          if (f <= 0) continue;
          ctx.beginPath(); ctx.arc(cx, cy, rr, a0, a1);
          ctx.strokeStyle = a ? "rgba(47,107,255," + 0.35 * f + ")" : "rgba(" + C.line + "," + 0.9 * f + ")";
          ctx.lineWidth = 1; ctx.stroke();
        }
      }

      // land dots, batched by brightness
      var B = 8, paths = []; for (var b = 0; b < B; b++) paths.push(new Path2D());
      for (var i = 0; i < n; i++) {
        var o = i * 3, x = pts[o], y = pts[o + 1], z = pts[o + 2];
        var x1 = x * cl - z * sl, z1 = x * sl + z * cl;
        var z2 = y * sp + z1 * cp; if (z2 <= 0.02) continue;
        var y2 = y * cp - z1 * sp, sy = cy - y2 * R; if (sy > H) continue;
        var sx = cx + x1 * R; if (sx < -4 || sx > W + 4) continue;
        var v = (0.25 + 0.75 * z2) * fade(sy); if (v <= 0.02) continue;
        var bi = Math.min(B - 1, Math.floor(v * B));
        paths[bi].rect(sx - 0.8, sy - 0.8, 1.6, 1.6);
      }
      for (b = 0; b < B; b++) { ctx.fillStyle = "rgba(" + C.dot + "," + ((b + 1) / B) * 0.75 + ")"; ctx.fill(paths[b]); }

      // Agadir + links
      var A = xyz(AGADIR[0], AGADIR[1]), pa = proj(A[0], A[1], A[2]);
      if (pa[2] > 0) {
        for (var k = 0; k < LINKS.length; k++) {
          var Lk = xyz(LINKS[k][0], LINKS[k][1]), pb = proj(Lk[0], Lk[1], Lk[2]);
          var dx = pb[0] - pa[0], dy = pb[1] - pa[1], dist = Math.sqrt(dx * dx + dy * dy);
          var qx = (pa[0] + pb[0]) / 2, qy = (pa[1] + pb[1]) / 2 - dist * 0.55 - 6;
          ctx.beginPath(); ctx.moveTo(pa[0], pa[1]); ctx.quadraticCurveTo(qx, qy, pb[0], pb[1]);
          ctx.strokeStyle = "rgba(47,107,255,0.55)"; ctx.lineWidth = 1; ctx.stroke();
          ctx.fillStyle = "rgba(" + C.dot + ",0.9)"; ctx.fillRect(pb[0] - 1.2, pb[1] - 1.2, 2.4, 2.4);
          if (!reduce) {
            var u = ((t / 2600 + k / LINKS.length) % 1), iu = 1 - u;
            var ex = iu * iu * pa[0] + 2 * iu * u * qx + u * u * pb[0], ey = iu * iu * pa[1] + 2 * iu * u * qy + u * u * pb[1];
            ctx.fillStyle = "rgba(" + C.accent + "," + Math.sin(u * Math.PI) + ")";
            ctx.beginPath(); ctx.arc(ex, ey, 1.6, 0, Math.PI * 2); ctx.fill();
          }
        }
        var ph = reduce ? 0.5 : (t % 2400) / 2400;
        ctx.beginPath(); ctx.arc(pa[0], pa[1], 3 + ph * 20, 0, Math.PI * 2);
        ctx.strokeStyle = "rgba(" + C.accent + "," + (1 - ph) * 0.8 + ")"; ctx.lineWidth = 1; ctx.stroke();
        ctx.beginPath(); ctx.arc(pa[0], pa[1], 3, 0, Math.PI * 2); ctx.fillStyle = "rgb(" + C.accent + ")"; ctx.fill();
        // label
        var lx = pa[0] - 18, ly = pa[1] - 40;
        ctx.beginPath(); ctx.moveTo(pa[0] - 3, pa[1] - 3); ctx.lineTo(lx, ly + 6); ctx.lineTo(lx - 22, ly + 6);
        ctx.strokeStyle = "rgba(" + C.muted + ",0.7)"; ctx.stroke();
        ctx.font = "500 10px " + mono; ctx.textAlign = "right"; ctx.fillStyle = "rgba(" + C.text + ",0.95)";
        ctx.fillText("AGADIR", lx - 26, ly + 4);
        ctx.fillStyle = "rgba(" + C.muted + ",0.9)"; ctx.fillText("30.42°N 9.60°W", lx - 26, ly + 17);
      }
    }

    function loop(t) {
      px += (tpx - px) * 0.04;
      frame(t);
      if (!reduce && visible && !document.hidden) raf = requestAnimationFrame(loop); else raf = 0;
    }
    function start() { if (!raf) raf = requestAnimationFrame(loop); }

    build(); frame(0);
    new ResizeObserver(function () { build(); frame(performance.now()); }).observe(canvas);
    new IntersectionObserver(function (es) { visible = es[0].isIntersecting; if (visible) start(); }).observe(canvas);
    document.addEventListener("visibilitychange", function () { if (!document.hidden) start(); });
    window.addEventListener("pointermove", function (e) { if (e.pointerType === "mouse") tpx = (e.clientX / window.innerWidth) * 2 - 1; }, { passive: true });
    start();
  }

  function scan() { document.querySelectorAll("canvas[data-globe]").forEach(init); }
  scan();
  new MutationObserver(scan).observe(document.documentElement, { childList: true, subtree: true });
})();
